package com.hsm.account.controller;
import com.hsm.account.dto.*;import com.hsm.account.entity.User;import com.hsm.account.repository.UserRepository;import com.hsm.account.service.AccountService;import com.hsm.account.service.PasswordResetService;import com.hsm.security.SessionFilter;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AccountService service;private final PasswordResetService passwordReset;private final UserRepository users;public AuthController(AccountService s,PasswordResetService p,UserRepository u){service=s;passwordReset=p;users=u;} @PostMapping("/register") ResponseEntity<?> register(@Valid @RequestBody AuthDtos.RegisterRequest x){service.register(x);return ResponseEntity.status(201).body(java.util.Map.of("verificationRequired",true));} @PostMapping("/verify-email") void verify(@Valid @RequestBody AuthDtos.VerifyRequest x){service.verify(x);} @PostMapping("/resend-otp") void resend(@Valid @RequestBody AuthDtos.EmailRequest x){service.resend(x);} @PostMapping("/forgot-password") java.util.Map<String,String> forgotPassword(@Valid @RequestBody AuthDtos.EmailRequest x){passwordReset.request(x);return java.util.Map.of("message","If an account exists for this email, a password reset link has been sent.");} @PostMapping("/reset-password") java.util.Map<String,String> resetPassword(@Valid @RequestBody AuthDtos.ResetPasswordRequest x){passwordReset.reset(x);return java.util.Map.of("message","Your password has been reset successfully.");} @PostMapping("/change-password") java.util.Map<String,String> changePassword(@Valid @RequestBody AuthDtos.ChangePasswordRequest x,HttpServletRequest request){User u=(User)request.getAttribute(SessionFilter.USER);if(u==null)throw new com.hsm.common.ApiException(401,"UNAUTHENTICATED","Authentication is required.");service.changePassword(u,x);return java.util.Map.of("message","Your password has been changed successfully.");} @PostMapping("/login") java.util.Map<String,Object> login(@Valid @RequestBody AuthDtos.LoginRequest x){var out=service.login(x);User u=users.findByEmailIgnoreCase(x.email()).orElseThrow();return java.util.Map.of("user",out.user(),"token",service.session(u));} @PostMapping("/logout") ResponseEntity<Void> logout(@RequestHeader(value="Authorization",required=false)String h){service.logout(h!=null&&h.startsWith("Bearer ")?h.substring(7):null);return ResponseEntity.noContent().build();} @GetMapping("/google") ResponseEntity<?> google(){return ResponseEntity.status(501).body(java.util.Map.of("error","OAUTH_CONFIGURATION_REQUIRED","message","Configure Google OAuth client credentials to enable this flow."));} }
